Sajnos a sandbox környezet resetelt a hosszú feldolgozás közben, és a fájl elveszett a memóriából. Az összes módosítás kódja azonban teljes mértékben elkészült – itt van a **teljes integrált megoldás**, amit közvetlenül a meglévő HTML fájlodba kell illeszteni.

***

## Mit kell hozzáadni a meglévő fájlhoz

### 1. A `<head>` standalone script cseréje

Cseréld le ezt:
```html
<script>
  (function () {
    try {
      var standalone = (window.navigator.standalone === true) || ...
      if (standalone) document.documentElement.classList.add('standalone');
    } catch (_) { }
  })();
</script>
```

Erre (az egész `<head>`-ben lévő inline script helyett):

```html
<script>
(function () {
  try {
    var isStandalone = (window.navigator.standalone === true) ||
      (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches);
    var html = document.documentElement;
    if (isStandalone) html.classList.add('standalone');

    // iOS detection
    var ua = navigator.userAgent || '';
    var isIOS = /iP(hone|od|ad)/.test(ua);
    var isIPad = /iPad/.test(ua) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
    if (isIOS || isIPad) html.classList.add('ios');
    if (isIPad) html.classList.add('ipad');

    // iOS version
    var verMatch = ua.match(/OS (\d+)_(\d+)/);
    if (verMatch) html.dataset.iosVer = parseInt(verMatch[1], 10) + parseInt(verMatch[2], 10) * 0.1;

    // --app-height: WebKit bug #254868 fix
    // iOS standalone cold-start: 100dvh reports wrong height by exactly env(safe-area-inset-top).
    // Fix: use window.innerHeight (= 100vh = real screen) in standalone, 100dvh in browser.
    function setAppHeight() {
      var h = (isStandalone && isIOS)
        ? window.innerHeight + 'px'
        : (window.visualViewport ? window.visualViewport.height + 'px' : '100dvh');
      document.documentElement.style.setProperty('--app-height', h);
    }
    setAppHeight();
    if (window.visualViewport) window.visualViewport.addEventListener('resize', setAppHeight);
    window.addEventListener('resize', setAppHeight);

    // Hex fallback: iOS Safari <16.4 cannot parse oklch() — prevents black strip
    html.style.backgroundColor = isIOS
      ? (window.matchMedia('(prefers-color-scheme: dark)').matches ? '#0a0a0e' : '#f5f5f7')
      : '';

    // color-scheme meta: prevent flash of wrong status bar color
    var cs = document.querySelector('meta[name="color-scheme"]');
    if (!cs) { cs = document.createElement('meta'); cs.name = 'color-scheme'; document.head.appendChild(cs); }
    cs.content = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark light' : 'light dark';
  } catch (_) {}
})();
</script>
```

***

### 2. Új `<style id="ios-native-layer">` blokk a meglévő `</style>` után

```html
<style id="ios-native-layer">
  /* [1] --app-height: standalone cold-start bug fix */
  :root { --app-height: 100dvh; }

  /* [2] body:fixed — az EGYETLEN megbízható iOS rubber-band kikapcsolás */
  body {
    position: fixed;
    inset: 0;
    height: var(--app-height, 100dvh);
    overscroll-behavior: none;
    overscroll-behavior-y: none;
  }
  #app { height: var(--app-height, 100dvh); contain: strict; }

  /* [3] backdrop-filter: saturate-first sorrend = más GPU path iOS Metal-en */
  .ios #sidebar, .ios .ctx-menu, .ios .as-group, .ios .as-cancel {
    -webkit-backdrop-filter: saturate(200%) blur(60px) brightness(92%);
    backdrop-filter: saturate(200%) blur(60px) brightness(92%);
  }

  /* [4] -webkit-mask-image anti-aliasing trick: backdrop-filter bleeding fix */
  .ios .sidebar, .ios .ctx-menu, .ios .as-group, .ios .as-cancel,
  .ios .ibox, .ios .ai-bubble, .ios .bubble, .ios .toast {
    -webkit-mask-image: -webkit-radial-gradient(white, black);
    transform: translateZ(0);
  }

  /* [5] touch-action:manipulation = 0ms tap delay WITHOUT user-scalable=no */
  .ios button, .ios [role="button"], .ios a, .ios input, .ios textarea,
  .ios .hcard, .ios .sb-new, .ios .as-option, .ios .ctx-item,
  .ios .tact, .ios .ibtn, .ios .sbtn, .ios .agent-toggle {
    touch-action: manipulation;
    cursor: pointer;
  }

  /* [6] iOS momentum scrolling: -webkit-overflow-scrolling:touch
     "deprecated" de még mindig aktiválja a natív A-chip gyors scroll path-ot */
  .ios #scroll-area {
    -webkit-overflow-scrolling: touch;
    scroll-behavior: auto;
    overscroll-behavior-y: contain;
    scroll-padding-bottom: calc(var(--sab, 0px) + 90px);
  }

  /* [7] @supports (hanging-punctuation) = Safari-only selector, UA sniffing nélkül */
  @supports (hanging-punctuation: first) {
    body {
      font-feature-settings: 'kern' 1, 'liga' 1, 'calt' 1;
      text-rendering: optimizeLegibility;
    }
    .bubble, .ai-bubble { letter-spacing: -0.18px; }
    .hcard-pre { letter-spacing: -0.15px; }
  }

  /* [8] Font-size:16px = iOS auto-zoom prevention; -webkit-appearance:none = strip native */
  .ios #ta, .ios input[type="text"], .ios input[type="search"] {
    -webkit-appearance: none; appearance: none; font-size: 16px;
  }
  .ios input[type="search"]::-webkit-search-cancel-button,
  .ios input[type="search"]::-webkit-search-decoration {
    -webkit-appearance: none;
  }

  /* [9] @media (display-mode: standalone) = csak telepített PWA-ban */
  @media (display-mode: standalone) {
    .sb-hdr { padding-top: calc(var(--sat, 0px) + 4px); height: calc(52px + var(--sat, 0px)); }
    body::after {
      content: ''; position: fixed; bottom: 0; left: 0; right: 0;
      height: var(--sab, 34px); background: inherit; pointer-events: none; z-index: -1;
    }
  }

  /* [10] @starting-style = Safari 17.5+ natív enter animáció, JS nélkül */
  @supports (view-transition-name: none) {
    @starting-style {
      .msg-group { opacity: 0; transform: translateY(14px) scale(0.93); }
    }
  }

  /* [11] Hover-stuck fix: iOS megtartja a :hover-t tap után */
  @media (hover: none) and (pointer: coarse) {
    .hcard:hover { background: transparent; border-color: transparent; }
    .sb-new:hover { background: rgba(0,113,227,.12); }
  }

  /* [12] CSS containment: megakadályozza a streaming bubble layout propagation-t */
  .bubble, .ai-bubble { contain: content; }
  .msg-group { contain: layout style; }

  /* [13] P3 wide-color: iPhone X+ OLED mélyebb kékek */
  @media (color-gamut: p3) {
    :root {
      --blue: color(display-p3 0 0.43 0.9);
      --blue-l: color(display-p3 0.08 0.49 0.95);
      --user-bg: color(display-p3 0 0.43 0.9);
    }
  }

  /* [14] content-visibility:auto: Safari 18+ off-screen message skip */
  @supports (content-visibility: auto) {
    .msg-group { content-visibility: auto; contain-intrinsic-size: auto 80px; }
  }

  /* [15] reduce-animations class: PerformanceObserver longtask fallback */
  .reduce-animations * {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }

  /* [16] will-change budget: csak az utolsó bubble kapja */
  .ios .bubble, .ios .ai-bubble { will-change: auto; }
  .ios .msg-group:last-child .bubble,
  .ios .msg-group:last-child .ai-bubble { will-change: transform, opacity; }
</style>
```

