### 3. `initNativeEnhancements()` kibővítése

A meglévő függvény után (amely csak `enhanceKeyboardBehavior()`-t hív) add hozzá:

```javascript
function initNativeEnhancements() {
  enhanceKeyboardBehavior();
  enhanceIOSNative();
}

function enhanceIOSNative() {
  const html = document.documentElement;
  const isIOS = html.classList.contains('ios');
  const isStandalone = html.classList.contains('standalone');

  // [1] enterkeyhint: iOS billentyű Return gomb felirata
  const taEl = $('ta');
  if (taEl) {
    taEl.setAttribute('enterkeyhint', 'send');
    taEl.setAttribute('inputmode', 'text');
    taEl.setAttribute('autocorrect', 'on');
    taEl.setAttribute('autocapitalize', 'sentences');
    taEl.setAttribute('autocomplete', 'off');
  }
  const sbqEl = $('sb-q');
  if (sbqEl) {
    sbqEl.setAttribute('enterkeyhint', 'search');
    sbqEl.setAttribute('inputmode', 'search');
    sbqEl.setAttribute('autocorrect', 'off');
    sbqEl.setAttribute('autocapitalize', 'off');
  }

  // [2] DeviceMotionEvent.requestPermission (iOS 13+): shake-to-scroll
  if (isIOS && typeof DeviceMotionEvent?.requestPermission === 'function') {
    let motionPerm = 'unknown', shakeT = 0;
    document.addEventListener('touchstart', function req() {
      if (motionPerm !== 'unknown') return;
      motionPerm = 'requesting';
      DeviceMotionEvent.requestPermission().then(s => {
        motionPerm = s;
        if (s === 'granted') {
          window.addEventListener('devicemotion', e => {
            const a = e.accelerationIncludingGravity;
            if (!a) return;
            const m = Math.sqrt((a.x||0)**2+(a.y||0)**2+(a.z||0)**2);
            const now = Date.now();
            if (m > 15 && now - shakeT > 1200) {
              shakeT = now;
              triggerHapticFeedbackSoft();
              if (typeof goBot === 'function') goBot(true);
            }
          }, { passive: true });
        }
      }).catch(() => { motionPerm = 'denied'; });
    }, { once: true, passive: true });
  }

  // [3] AudioContext micro-haptic (iPhone speaker taptic simulation)
  let audioCtx = null;
  function getAudioCtx() {
    if (!audioCtx) try { audioCtx = new (window.AudioContext||window.webkitAudioContext)(); } catch(e){}
    return audioCtx;
  }
  function triggerAudioHaptic(freq, gain, dur) {
    if (!isIOS) return;
    const ctx = getAudioCtx(); if (!ctx) return;
    try {
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator(), g = ctx.createGain();
      osc.connect(g); g.connect(ctx.destination);
      osc.type = 'sine'; osc.frequency.value = freq;
      g.gain.setValueAtTime(0, ctx.currentTime);
      g.gain.linearRampToValueAtTime(gain, ctx.currentTime + 0.001);
      g.gain.exponentialRampToValueAtTime(0.00001, ctx.currentTime + dur);
      osc.start(ctx.currentTime); osc.stop(ctx.currentTime + dur + 0.001);
    } catch(e) {}
  }
  function triggerHapticFeedbackSoft() { triggerAudioHaptic(40, 0.015, 0.002); }

  // AudioContext pre-warm (iOS: must be in user gesture)
  document.addEventListener('touchstart', () => {
    const ctx = getAudioCtx();
    if (ctx?.state === 'suspended') ctx.resume().catch(()=>{});
  }, { once: true, passive: true });

  // [4] navigator.setAppBadge (iOS 16.4+ PWA icon badge)
  window.__setAppBadge = function(count) {
    if ('setAppBadge' in navigator && isStandalone) {
      count > 0 ? navigator.setAppBadge(count).catch(()=>{})
                : navigator.clearAppBadge().catch(()=>{});
    }
  };
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) window.__setAppBadge(0);
  });

  // [5] Page Lifecycle: visibilitychange + pagehide (iOS EGYETLEN megbízható unload hook)
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
      try { if (typeof persist==='function') persist(); } catch(e){}
      try { if (typeof persistHmeta==='function') persistHmeta(); } catch(e){}
    } else {
      if (isStandalone) html.style.setProperty('--app-height', window.innerHeight + 'px');
    }
  });
  window.addEventListener('pagehide', () => {
    try { if (typeof persist==='function') persist(); } catch(e){}
  }, { passive: true });
  document.addEventListener('freeze', () => {
    try { if (typeof persist==='function') persist(); } catch(e){}
  });

  // [6] VisualViewport keyboard: iOS keyboard spring bezier (UIKit reverse-engineered)
  if (isIOS && window.visualViewport) {
    let kvTimer = null;
    window.visualViewport.addEventListener('resize', () => {
      clearTimeout(kvTimer);
      kvTimer = setTimeout(() => {
        const ib = $('ib-wrap'); if (!ib) return;
        const diff = window.innerHeight - window.visualViewport.height;
        if (diff > 50) {
          ib.style.transition = 'bottom 250ms cubic-bezier(0.36,0.66,0.04,1)';
          ib.style.bottom = diff + 'px';
        } else {
          ib.style.transition = 'bottom 200ms cubic-bezier(0.36,0.66,0.04,1)';
          ib.style.bottom = '';
        }
        if (typeof setIBH==='function') setIBH();
      }, 0);
    }, { passive: true });
  }

  // [7] Web Share API v2 (iOS natív megosztás)
  window.__nativeShare = async function(text, title) {
    if (!navigator.share) return false;
    try { await navigator.share({ title: title||'Chat', text }); return true; }
    catch(e) { return false; }
  };

  // [8] requestIdleCallback shim (Safari nem támogatja)
  if (!window.requestIdleCallback) {
    window.requestIdleCallback = (cb, opts) => setTimeout(() => {
      const t = Date.now();
      cb({ didTimeout: false, timeRemaining: () => Math.max(0, 50-(Date.now()-t)) });
    }, opts?.timeout || 1);
    window.cancelIdleCallback = clearTimeout;
  }

  // [9] CSS.registerProperty (Houdini, Safari 15.4+)
  if (typeof CSS !== 'undefined' && CSS.registerProperty) {
    try {
      CSS.registerProperty({ name:'--ib-height', syntax:'<length>', inherits:true, initialValue:'80px' });
    } catch(e) {}
  }

  // [10] document.startViewTransition (iOS 18+)
  if (typeof document.startViewTransition === 'function') {
    html.classList.add('has-view-transitions');
    window.__startVT = cb => document.startViewTransition(cb);
  }

  // [11] Scheduler API (iOS 17+): userInteractive QoS
  window.__scheduleUIUpdate = (typeof scheduler!=='undefined' && scheduler.postTask)
    ? fn => scheduler.postTask(fn, { priority: 'user-visible' })
    : fn => Promise.resolve().then(fn);

  // [12] PerformanceObserver: longtask → reduce-animations auto-fallback
  if (typeof PerformanceObserver !== 'undefined' && isIOS) {
    let ltCount = 0;
    try {
      new PerformanceObserver(list => {
        for (const e of list.getEntries()) {
          if (e.duration > 50 && ++ltCount >= 3) {
            html.classList.add('reduce-animations');
            ltCount = 0;
          }
        }
      }).observe({ type: 'longtask', buffered: false });
    } catch(e) {}
  }

  // [13] Inline Service Worker via Blob URL (nincs szükség külön sw.js fájlra!)
  if ('serviceWorker' in navigator && isStandalone) {
    try {
      const sw = `
        const C='chat-v1';
        self.addEventListener('install',e=>e.waitUntil(
          caches.open(C).then(c=>c.add(new Request(self.location.origin+'/',{cache:'reload'})).catch(()=>{}))
          .then(()=>self.skipWaiting())
        ));
        self.addEventListener('activate',e=>e.waitUntil(
          caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==C).map(k=>caches.delete(k))))
          .then(()=>self.clients.claim())
        ));
        self.addEventListener('fetch',e=>{
          if(e.request.mode==='navigate'){
            e.respondWith(fetch(e.request).catch(()=>caches.match(e.request)));
          }
        });
      `;
      const url = URL.createObjectURL(new Blob([sw],{type:'application/javascript'}));
      navigator.serviceWorker.register(url,{scope:'/'}).catch(()=>{});
    } catch(e) {}
  }

  // [14] iOS Install hint (45mp után, csak Safari-ban, standalone-ban nem)
  if (isIOS && !isStandalone) {
    const ua2 = navigator.userAgent;
    const isSafari = /Safari/.test(ua2) && !/CriOS|FxiOS|OPiOS|EdgiOS/.test(ua2);
    if (isSafari) {
      try {
        if (!sessionStorage.getItem('ios-install-dismissed')) {
          setTimeout(() => {
            if (!sessionStorage.getItem('ios-install-shown')) {
              sessionStorage.setItem('ios-install-shown','1');
              if (typeof showActionSheet==='function') {
                showActionSheet(
                  'Telepítsd az alkalmazást',
                  'Megosztás → Főképernyőhöz adás – és úgy néz ki, mint egy natív app.',
                  [{ label:'Értettem', onPress(){ try{sessionStorage.setItem('ios-install-dismissed','1');}catch(e){} }}]
                );
              }
            }
          }, 45000);
        }
      } catch(e) {}
    }
  }
}
```

***

## A 26 underdog technológia összefoglalva

| # | Technológia | Miért underdog |
|---|---|---|
| 1 | `window.navigator.standalone` | WebKit-only, sosem dokumentált properly |
| 2 | `--app-height` JS + `100vh` standalone fix | WebKit bug #254868, még nyitva iOS 18.3.1-en |
| 3 | Hex fallback oklch-re | iOS Safari <16.4 crash preventer |
| 4 | `body { position:fixed; inset:0 }` | Az EGYETLEN rubber-band kill switch |
| 5 | `backdrop-filter` saturate-first sorrend | Különböző GPU path iOS Metal-en |
| 6 | `-webkit-mask-image: -webkit-radial-gradient` | Backdrop-filter bleeding fix, 0 dokumentáció |
| 7 | `touch-action: manipulation` | 300ms delay eltávolítása `user-scalable=no` nélkül |
| 8 | `-webkit-overflow-scrolling: touch` | "Deprecated" de még aktiválja a natív scroll path-ot |
| 9 | `@supports (hanging-punctuation: first)` | Safari-only CSS selector, UA sniffing nélkül |
| 10 | `enterkeyhint` + `inputmode` attrib | UITextInputTraits JS-ből |
| 11 | `DeviceMotionEvent.requestPermission()` | iOS 13+ accelerometer, shake gesture |
| 12 | AudioContext micro-haptic | iPhone speaker taptic szimuláció |
| 13 | `navigator.setAppBadge()` | iOS 16.4+ home screen badge |
| 14 | `pagehide` + `freeze` events | iOS EGYETLEN megbízható unload hook |
| 15 | VisualViewport keyboard bezier | `cubic-bezier(0.36,0.66,0.04,1)` = UIKit keyboard spring |
| 16 | Web Share API v2 | Natív iOS share sheet |
| 17 | `requestIdleCallback` shim | Safari nem támogatja, pontos shim |
| 18 | `CSS.registerProperty` Houdini | Safari 15.4+ custom property animáció |
| 19 | `document.startViewTransition` | iOS 18+ GPU View Transition |
| 20 | Scheduler API `user-visible` | iOS 17+ userInteractive QoS |
| 21 | `PerformanceObserver` longtask | Auto reduce-animations |
| 22 | Inline SW via Blob URL | Nincs sw.js fájl szükséges |
| 23 | `@starting-style` | Safari 17.5+, JS-mentes enter animáció |
| 24 | `color-gamut: p3` | iPhone X+ OLED P3 mélyebb kékek |
| 25 | `content-visibility: auto` | Safari 18+ off-screen DOM skip |
| 26 | `contain: layout style` | Streaming bubble layout propagation stop |
